import{_ as t,o,c as a,a2 as l}from"./chunks/framework.CdvW4CUT.js";const s=JSON.parse('{"title":"傳送/設定記錄點","description":"傳送指令及設定紀錄點。","frontmatter":{"title":"傳送/設定記錄點","description":"傳送指令及設定紀錄點。"},"headers":[],"relativePath":"feature/teleport/index.md","filePath":"feature/teleport.md"}'),c={name:"feature/teleport/index.md"};function i(d,e,r,p,b,n){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="傳送-設定記錄點" tabindex="-1">傳送/設定記錄點 <a class="header-anchor" href="#傳送-設定記錄點" aria-label="Permalink to &quot;傳送/設定記錄點&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">公告(2022/07/01)</p><p>目前除了<code>/tpa</code>相關傳送，皆可跨分流傳送，其相關開發已在排程中，敬請期待</p></div><h2 id="一般傳送" tabindex="-1">一般傳送 <a class="header-anchor" href="#一般傳送" aria-label="Permalink to &quot;一般傳送&quot;">​</a></h2><ul><li><code>/spawn</code><b>返回至分流重生點</b></li><li><code>/back</code><b>回去上一個傳送點</b><blockquote><p>說明：當你使用任何傳送指令時會記錄傳送點，輸入此指令就能回去<br> 備註：死亡時也會記錄 可使用<code>/back</code>回去死亡點</p></blockquote></li></ul><h2 id="請求傳送" tabindex="-1">請求傳送 <a class="header-anchor" href="#請求傳送" aria-label="Permalink to &quot;請求傳送&quot;">​</a></h2><ul><li><p><code>/tpa &lt;玩家ID&gt;</code><b>請求傳送至對方那邊</b> 你--&gt;對方</p></li><li><p><code>/tpahere &lt;玩家ID&gt;</code><b>請求&quot;對方&quot;傳送至你這邊</b> 對方--&gt;你</p><blockquote><p>請求傳送指令 (tpa tpahere) 時效皆為 60 秒<br> 如果對方超過時間沒回應 即視為拒絕此請求</p></blockquote></li><li><p><code>/tpaccept</code><b>接受最近的傳送請求</b></p></li><li><p><code>/tpaccept &lt;玩家ID&gt;</code><b>接受指定玩家的傳送請求</b></p></li><li><p><code>/tpdeny</code><b>拒絕最近的傳送請求</b></p></li><li><p><code>/tpdeny &lt;玩家ID&gt;</code><b>拒絕指定玩家的傳送請求</b></p></li><li><p>請不要使用此功能對其他玩家洗頻，若遇到可以<a href="/apply/report/">檢舉</a></p></li></ul><h2 id="設定紀錄點" tabindex="-1">設定紀錄點 <a class="header-anchor" href="#設定紀錄點" aria-label="Permalink to &quot;設定紀錄點&quot;">​</a></h2><p>可以記錄地點並在你需要時傳送，很方便的功能<br> 像是記錄自己家的位置，隨時可以回家</p><ul><li><code>/sethome &lt;家的名稱&gt;</code><b>設定家的位置</b><blockquote><p>一般玩家最多可擁有 5個紀錄點(全伺服共用)<br> 贊助者可依照贊助金額獲得更多紀錄點<br> 詳見<a href="/donate/">贊助伺服</a></p></blockquote></li><li><code>/home &lt;家的名稱&gt;</code><b>傳送回家</b></li><li><code>/delhome &lt;家的名稱&gt;</code><b>刪除現有的家</b></li><li><code>/homelist</code><b>查看你擁有的家及位置</b></li></ul><h2 id="傳送冷卻" tabindex="-1">傳送冷卻 <a class="header-anchor" href="#傳送冷卻" aria-label="Permalink to &quot;傳送冷卻&quot;">​</a></h2><p>一般玩家使用傳送(不包含<code>/tpahere</code>相關)的冷卻時間為<b>15秒</b></p><blockquote><p>贊助者可依照贊助金額縮短冷卻時間 詳見<a href="/donate/">贊助伺服</a></p></blockquote>',12)])])}const u=t(c,[["render",i]]);export{s as __pageData,u as default};
